mapper.update:
UPDATE `bitable_tables`
SET sort_order = CASE id

        WHEN #{id} THEN #{idx}

END
WHERE base_id = #{baseId}
  AND deleted_at = 0
  AND id IN

    #{id}

mapper.select:
SELECT COUNT(*)
FROM `bitable_tables` t
INNER JOIN `bitable_bases` b ON b.id = t.base_id AND b.deleted_at = 0
WHERE t.deleted_at = 0
  AND t.name = #{name}
  AND COALESCE(t.base_group_id, b.group_id) <=> #{groupId}

  AND t.id != #{excludeId}
